# Filter out automatic messages and look only at human-typed messages
python3 << 'EOF'
import json, glob, os, re

dirs = glob.glob('/home/ubuntu/.claude-account-*/projects/*director-b268826c/*.jsonl')
unique = {}
for p in dirs:
    name = os.path.basename(p)
    if name not in unique or os.path.getsize(p) > os.path.getsize(unique[name]):
        unique[name] = p

human_msgs = []
for p in sorted(unique.values(), key=os.path.getmtime):
    try:
        with open(p) as f:
            for line in f:
                try:
                    rec = json.loads(line)
                    if rec.get('type') != 'user': continue
                    msg = rec.get('message', {})
                    if not isinstance(msg, dict): continue
                    content = msg.get('content', '')
                    if isinstance(content, str):
                        t = content
                    elif isinstance(content, list):
                        texts = []
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'text':
                                texts.append(c.get('text', ''))
                        t = '\n'.join(texts)
                    else:
                        continue
                    if not t.strip(): continue
                    # Filter to actual user human messages
                    if re.search(r'\[飞书用户', t) or re.search(r'\[Director feedback from user', t) or t.strip().startswith('[user'):
                        human_msgs.append((rec.get('timestamp',''), os.path.basename(p)[:10], t[:1000]))
                except: pass
    except: pass

print(f'Human messages (feishu user): {len(human_msgs)}')
print('First 10:')
for ts, p, txt in human_msgs[:10]:
    txt_clean = re.sub(r'\s+', ' ', txt).strip()[:280]
    print(f"\n  [{ts[:16]}] {p}\n    {txt_clean}")
print()
print('Last 10:')
for ts, p, txt in human_msgs[-10:]:
    txt_clean = re.sub(r'\s+', ' ', txt).strip()[:280]
    print(f"\n  [{ts[:16]}] {p}\n    {txt_clean}")
EOF
